import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.Dc-w_e1r.js";const u=JSON.parse('{"title":"Управление API ключами","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-keys.md","filePath":"guide/api-keys.md"}'),o={name:"guide/api-keys.md"};function l(r,a,n,d,p,c){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="управление-api-ключами" tabindex="-1">Управление API ключами <a class="header-anchor" href="#управление-api-ключами" aria-label="Permalink to &quot;Управление API ключами&quot;">​</a></h1><p>API ключ — это ваш идентификатор для доступа к OpenRussiaRouter API. Один ключ работает со всеми моделями.</p><h2 id="создание-ключа" tabindex="-1">Создание ключа <a class="header-anchor" href="#создание-ключа" aria-label="Permalink to &quot;Создание ключа&quot;">​</a></h2><ol><li>Перейдите в панель управления.</li><li>В разделе &quot;API ключи&quot; нажмите создать.</li><li>Скопируйте сгенерированный ключ (формат <code>sk-or-&lt;36 случайных символов&gt;</code>).</li></ol><div class="warning custom-block"><p class="custom-block-title">Сохраните ключ</p><p>Полный ключ (raw) показывается только один раз при создании. В нашей базе данных сохраняется только его безопасный SHA-256 хеш. Если вы потеряли ключ, вам придется его отозвать и создать новый.</p></div><h2 id="формат-ключа" tabindex="-1">Формат ключа <a class="header-anchor" href="#формат-ключа" aria-label="Permalink to &quot;Формат ключа&quot;">​</a></h2><p>Все ключи OpenRussiaRouter начинаются с префикса <code>sk-or-</code>. Используйте ключ в заголовке <code>Authorization</code> при отправке HTTP-запросов:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer sk-or-xxx</span></span></code></pre></div><h2 id="безопасность" tabindex="-1">Безопасность <a class="header-anchor" href="#безопасность" aria-label="Permalink to &quot;Безопасность&quot;">​</a></h2><ul><li><strong>Не коммитьте ключи в код.</strong> Используйте переменные окружения (<code>.env</code>).</li><li><strong>Своевременно отзывайте ключи</strong>, если подозреваете, что они были скомпрометированы.</li><li>Вы можете создать несколько ключей для разных проектов или сред разработки.</li></ul>',10)])])}const k=e(o,[["render",l]]);export{u as __pageData,k as default};
